            self.on_event = on_event
            self.asset_ids = asset_ids
            self._ws = None
            self._thread = None
            self._stop_flag = threading.Event()
        def _on_message(self, ws, message):
            if message == "PONG": return
            try:
                data = json.loads(message)
                if isinstance(data, list):
